// Get all input items. WF3P receives its payload over a webhook from WF2P,
// so the actual data may sit under item.json.body (single object or array).
const rawItems = $input.all();
const allItems = [];
rawItems.forEach(item => {
  const j = item.json || {};
  if (j.body !== undefined && j.body !== null && typeof j.body === 'object') {
    if (Array.isArray(j.body)) {
      j.body.forEach(b => allItems.push({ json: b }));
    } else {
      allItems.push({ json: j.body });
    }
  } else {
    allItems.push({ json: j });
  }
});

// Debug the structure
console.log("Total items:", allItems.length);

// Extract data from the complex nested structure
let careersData = [];
let reportId = "";
let initialSummary = "";

// Process each item to find our data
allItems.forEach((item, index) => {
  console.log(`Item ${index} keys:`, Object.keys(item.json || {}));

  // Look for careers data
  if (item.json?.Tit_co_RID_data) {
    if (typeof item.json.Tit_co_RID_data === 'string') {
      try {
        careersData = JSON.parse(item.json.Tit_co_RID_data);
      } catch (e) {
        console.log("Error parsing careers data:", e);
      }
    } else if (Array.isArray(item.json.Tit_co_RID_data)) {
      careersData = item.json.Tit_co_RID_data;
    }
  }

  // Look for report ID
  if (item.json?.["report id"]) {
    reportId = item.json["report id"];
  }
  if (!reportId && item.json?.report_id) {
    reportId = item.json.report_id;
  }

  // Look for initial summary
  if (item.json?.["Initial Summary (output)"]) {
    initialSummary = item.json["Initial Summary (output)"];
  }
});

// Structure the final output with original field names
const result = {
  "report id": reportId,
  "Initial Summary (output)": initialSummary,
  Tit_co_RID_data: careersData
};

console.log("Final result structure:", {
  has_report_id: !!result["report id"],
  has_summary: !!result["Initial Summary (output)"],
  careers_count: result.Tit_co_RID_data.length
});

return [{ json: result }];

// Get profile items from current input (5 items from Pull Profile Sections)
const profileItems = $input.all();

// Define the desired order of sections
const sectionOrder = ['approach', 'strengths', 'development', 'values'];

// Create a map for quick lookup of items by section_type
const itemMap = {};
profileItems.forEach(item => {
  itemMap[item.json.section_type] = item.json.content;
});

// Combine content in the specified order
const combinedContent = sectionOrder
  .filter(sectionType => itemMap[sectionType]) // Only include sections that exist
  .map(sectionType => itemMap[sectionType])
  .join('\n\n---\n\n');

return [{
  json: {
    personality_profile: combinedContent
  }
}];

// Career Ranking Code Node - Step 2 Compatible Version (with title dedup)
// Encore v2 (2026-11-13, evals): Step 2 sometimes returns slightly broken JSON
// (a stray brace). parseScored repairs that; if fewer than 3 directions, or
// under 70% of the directions Step 2 wrote, survive, the node stops with an
// error so the report never goes out with an empty top 3 (the Error Handler alerts).
let expectedCareers = 0;
const stripFences = (t) => String(t || '').replace(/```json/gi, '').replace(/```/g, '').trim();
const tryParse = (t) => { try { return JSON.parse(t); } catch (e) { return null; } };
const careersOf = (p) => (p && Array.isArray(p.scored_careers)) ? p.scored_careers : null;
const parseScored = (raw) => {
  let t = stripFences(raw);
  expectedCareers += (t.match(/"career_title"/g) || []).length;
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a >= 0 && b > a) t = t.slice(a, b + 1);
  t = t.replace(/,\s*([}\]])/g, '$1');
  let got = careersOf(tryParse(t));
  if (got) return got;
  // One stray brace: try dropping each lone closing-brace line.
  const lines = t.split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (!/^\s*[}\]],?\s*$/.test(lines[i])) continue;
    got = careersOf(tryParse([...lines.slice(0, i), ...lines.slice(i + 1)].join('\n').replace(/,\s*([}\]])/g, '$1')));
    if (got) return got;
  }
  // Last resort: parse each career object on its own.
  const out = [];
  const starts = [];
  const re = /\{\s*"career_title"/g; let m;
  while ((m = re.exec(t))) starts.push(m.index);
  starts.forEach((s, k) => {
    let chunk = t.slice(s, k + 1 < starts.length ? starts[k + 1] : t.length).replace(/[\s,\]]*$/, '');
    for (let cut = 0; cut < 6 && chunk; cut++) {
      const p = tryParse(chunk);
      if (p && p.career_title) { out.push(p); return; }
      const cl = chunk.split('\n');
      let fixed = null;
      for (let i = 0; i < cl.length && !fixed; i++) {
        if (!/^\s*[}\]],?\s*$/.test(cl[i])) continue;
        const q = tryParse([...cl.slice(0, i), ...cl.slice(i + 1)].join('\n').replace(/,\s*([}\]])/g, '$1'));
        if (q && q.career_title) fixed = q;
      }
      if (fixed) { out.push(fixed); return; }
      chunk = chunk.replace(/\}\s*$/, '').trim();
    }
  });
  return out;
};

const allCareers = [];
for (const item of $input.all()) {
  const data = item.json;
  if (data.scored_careers && Array.isArray(data.scored_careers)) {
    allCareers.push(...data.scored_careers);
  } else if (data.text) {
    allCareers.push(...parseScored(data.text));
  } else if (data.CAI_scored_careers && Array.isArray(data.CAI_scored_careers)) {
    for (const entry of data.CAI_scored_careers) {
      if (entry.text) allCareers.push(...parseScored(entry.text));
      else if (entry.scored_careers && Array.isArray(entry.scored_careers)) allCareers.push(...entry.scored_careers);
      else if (entry.career_title) allCareers.push(entry);
    }
  }
}
// A cut-off answer hides missing directions from that count, so also compare
// with the number of options WF2P wrote (Pull enriched), when available.
try {
  const enrichedCount = $('Pull enriched').all().length;
  if (enrichedCount >= 5) expectedCareers = Math.max(expectedCareers, enrichedCount);
} catch (e) { /* not available: keep the count from the text */ }
if (allCareers.length < 3 || allCareers.length < expectedCareers * 0.7) {
  throw new Error(`Ranking: Step 2 scoring output could not be read (${allCareers.length} of ${expectedCareers} directions recovered). Stopped so the report is not sent with a broken top 3. Re-run WF3P for this report.`);
}

// Extract final score (Step 2 structure, normalized to /100).
// Encore v2: the score is summed HERE from its parts, not taken from the
// model's own addition. Each part is clamped to its allowed range, so a
// drifting model cannot push a direction past its real maximum.
// Falls back to the model's final_compatibility_score if a part is missing.
const num = (v) => {
  if (v === undefined || v === null) return NaN;
  if (typeof v === 'number') return v;
  const m = String(v).match(/-?\d+(\.\d+)?/);
  return m ? parseFloat(m[0]) : NaN;
};
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
// A missing or unreadable penalty counts as 0; a missing positive part
// means the scoring output is incomplete, so fall back (see getScore).
const pen0 = (v, max) => { const n = Math.abs(num(v)); return isNaN(n) ? 0 : -clamp(n, 0, max); };
const sumParts = (career) => {
  const p = career.step2_pattern_analysis || {};
  const pen = career.penalties || {};
  const parts = [
    clamp(num(career.step1_objective_score), 0, 64),
    clamp(num(p.happiness_pattern_match && p.happiness_pattern_match.score), 0, 20),
    clamp(num(p.strengths_application && p.strengths_application.score), 0, 14),
    clamp(num(p.trajectory_fit && p.trajectory_fit.score), 0, 10),
    pen0(pen.burnout_risk && pen.burnout_risk.penalty, 15),
    pen0(pen.development_conflicts && pen.development_conflicts.penalty, 8),
    pen0(pen.feasibility_penalty && pen.feasibility_penalty.penalty, 14)
  ];
  if (parts.some(x => isNaN(x))) return null;
  return clamp(parts.reduce((a, b) => a + b, 0), 0, 108);
};
const getScore = (career) => {
  let score = 0;
  const summed = sumParts(career);
  if (summed !== null) {
    score = summed;
  } else if (career.final_compatibility_score !== undefined) {
    score = parseInt(career.final_compatibility_score, 10);
    // Out-of-range model sums are garbage: rank them last, not first.
    score = (isNaN(score) || score < 0 || score > 108) ? 0 : score;
  } else if (career.compatibility_score !== undefined) {
    score = typeof career.compatibility_score === 'number'
      ? career.compatibility_score
      : parseInt(career.compatibility_score, 10);
  }
  return Math.round((Math.min(108, Math.max(0, score)) / 108) * 100);
};

const getSummary = (career) => {
  if (career.summary) {
    return {
      key_strengths: career.summary.key_strengths || '',
      key_concerns: career.summary.key_concerns || ''
    };
  }
  return {
    key_strengths: career.key_strengths || '',
    key_concerns: career.key_concerns || ''
  };
};

// Encore v2: wanted hours steer the ranking. [6.1] maps to a weekly range;
// a direction whose honest weekly hours (Step 2) sit far below that range
// loses points, and one far above it loses a few more (Step 2 already
// penalises overload). "It depends on the season" or a missing answer: no rule.
const facts = (($('Pull Init Summary').first().json.metadata) || {}).facts || {};
const WANTED_HOURS = {
  'a few hours a month': [0.5, 3],
  'half a day a week': [3, 6],
  'one or two days a week': [8, 16],
  'three days or more': [20, 40]
};
const wanted = WANTED_HOURS[String(facts.time || '').toLowerCase().trim()] || null;
const hoursOf = (career) => { const h = num(career.honest_hours_per_week); return isNaN(h) || h < 0 ? null : h; };
const hoursPenalty = (h) => {
  if (!wanted || h === null) return 0;
  const [lo, hi] = wanted;
  if (h < lo * 0.75) return Math.min(12, Math.round((1 - h / lo) * 12));
  if (h > hi * 1.5) return Math.min(6, 2 + Math.round((h / hi - 1.5) * 6));
  return 0;
};

// Score and sort
const sortedCareers = allCareers
  .map(career => {
    const summary = getSummary(career);
    const baseScore = getScore(career);
    const h = hoursOf(career);
    const hp = hoursPenalty(h);
    return {
      ...career,
      normalized_score: Math.max(0, baseScore - hp),
      hours_fit: { wanted_hours: wanted, honest_hours_per_week: h, adjustment: -hp },
      extracted_strengths: summary.key_strengths,
      extracted_concerns: summary.key_concerns
    };
  })
  .sort((a, b) => b.normalized_score - a.normalized_score);

// Title dedup pass — keep only the highest-scoring entry per unique title
function normalizeTitle(str) {
  if (!str) return '';
  return str.toLowerCase().replace(/\s+/g, ' ').trim();
}

const seenTitles = new Set();
const dedupedCareers = [];
const droppedDuplicates = [];

for (const career of sortedCareers) {
  const titleKey = normalizeTitle(career.career_title);
  if (!titleKey) continue;

  if (seenTitles.has(titleKey)) {
    droppedDuplicates.push({
      career_title: career.career_title,
      company_size_type: career.company_size_type,
      score: career.normalized_score
    });
    continue;
  }

  seenTitles.add(titleKey);
  dedupedCareers.push(career);
}

// Encore v2 gate: a direction that fails Step 1's basic requirements, or
// carries a HIGH hard-constraint violation (time, place, pay, energy,
// dignity), goes to the back of the list. It only reaches the top 3 when
// fewer than 3 clean directions exist, and never becomes a runner-up.
const isBlocked = (career) => {
  const g = career.step1_gate || {};
  const passes = String(g.passes_basic_requirements ?? 'true').toLowerCase().trim();
  const highs = Array.isArray(g.high_severity_violations)
    ? g.high_severity_violations.filter(v => v && !String(v).startsWith('['))
    : [];
  return passes === 'false' || highs.length > 0;
};
const gatedCareers = [
  ...dedupedCareers.filter(c => !isBlocked(c)),
  ...dedupedCareers.filter(c => isBlocked(c)).map(c => ({ ...c, blocked_by_gate: true }))
];

// Encore v2 variety: at most one direction per core activity in the top 3
// (round 3 gave Marjan three reading-aloud variants). Step 2 labels each
// direction's activity_family; labels count as the same activity when all
// words of the shorter label appear in the longer one ("reading aloud" and
// "reading aloud to children"), not when they share one word ("safety
// coordination" and "service coordination"). Skipped directions stay first in line
// for the runner-ups; if fewer than 3 distinct activities exist, they fill up.
const familyWords = (c) => String(c.activity_family || '').toLowerCase()
  .replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(w => w.length > 2 && !['and', 'the', 'for', 'with'].includes(w));
// Since 2026-11-13 Step 2 picks activity_family from a fixed list, so the same
// activity gets the same label in every run: equal labels = same activity.
// Labels outside the list ("other: ...") fall back to the word rule below.
const familyKey = (c) => String(c.activity_family || '').toLowerCase().replace(/\s+/g, ' ').trim();
const sameFamily = (a, b) => {
  const ka = familyKey(a), kb = familyKey(b);
  if (ka && kb && !ka.startsWith('other') && !kb.startsWith('other')) return ka === kb;
  const wa = familyWords(a), wb = familyWords(b);
  if (!wa.length || !wb.length) return false;
  const shared = wa.filter(w => wb.includes(w)).length;
  return shared === Math.min(wa.length, wb.length);
};
const topPicks = [];
const skippedForVariety = [];
for (const c of gatedCareers) {
  if (topPicks.length >= 3) break;
  if (c.blocked_by_gate) break;
  if (topPicks.some(p => sameFamily(p, c))) { skippedForVariety.push(c); continue; }
  topPicks.push(c);
}
for (const c of [...skippedForVariety, ...gatedCareers.filter(c => c.blocked_by_gate)]) {
  if (topPicks.length >= 3) break;
  if (!topPicks.includes(c)) topPicks.push(c);
}
// Encore v2 pay rule (Sjoerd, 2026-11-13): when extra income matters [6.4],
// a direction that pays nothing or little cannot be #1. If the top 3 holds no
// fairly paid direction, the best clean fairly paid one moves in at #1 (the
// third pick drops out); then the top 3 is ordered paid first, fit second.
// Step 2 sets pay_level per direction: none, low or fair.
const needsIncome = /^yes/i.test(String(facts.pay || '').trim());
const payTier = (c) => {
  const p = String(c.pay_level || '').toLowerCase().trim();
  return p === 'fair' ? 0 : (p === 'low' ? 1 : (p === 'none' ? 2 : 0));
};
let payReordered = false;
if (needsIncome && topPicks.length) {
  if (!topPicks.some(c => payTier(c) === 0)) {
    const paid = gatedCareers.find(c => !c.blocked_by_gate && !topPicks.includes(c) && payTier(c) === 0);
    if (paid) {
      if (topPicks.length >= 3) topPicks.pop();
      topPicks.unshift(paid);
      payReordered = true;
    }
  }
  const before = topPicks.map(c => c.career_title).join('|');
  topPicks.sort((a, b) => payTier(a) - payTier(b));
  if (topPicks.map(c => c.career_title).join('|') !== before) payReordered = true;
}
const orderedCareers = [...topPicks, ...gatedCareers.filter(c => !topPicks.includes(c))];

// Assign ranks on the deduped, gated, varied list
const rankedCareers = orderedCareers.map((career, index) => ({
  ...career,
  rank: index + 1
}));

// Slice Top 3 and Runner-ups (55+ threshold)
const top3 = rankedCareers.slice(0, 3);

// Combine hint for WF4P: they offered a day a week or more, and every top 3
// direction takes less than their minimum (Sjoerd 2026-11-13: "all three under
// minimum"). WF4P then says how two could be combined.
const top3Hours = top3.map(hoursOf);
const combineNeeded = !!wanted && wanted[0] >= 8 && top3.length === 3
  && top3Hours.every(h => h !== null && h < wanted[0]);
const runnerUps = rankedCareers
  .slice(3, 10)
  .filter(career => career.normalized_score >= 55 && !career.blocked_by_gate)
  .slice(0, 3);

// Format Top 3
const formattedTop3 = top3.map(career => ({
  rank: career.rank,
  career_title: career.career_title,
  company_size_type: career.company_size_type || "Unknown",
  compatibility_score: career.normalized_score,
  honest_hours_per_week: hoursOf(career),
  pay_level: career.pay_level || null,
  activity_family: career.activity_family || null,
  step1_objective_score: career.step1_objective_score || "N/A",
  pattern_analysis: career.step2_pattern_analysis || {},
  penalties: career.penalties || {},
  key_insights_applied: career.key_insights_applied || "",
  key_strengths: career.extracted_strengths,
  key_concerns: career.extracted_concerns,
  justification: career.extracted_strengths && career.extracted_concerns
    ? `${career.extracted_strengths} ${career.extracted_concerns}`
    : `Strong alignment with ${career.normalized_score}% compatibility score.`
}));

// Why a runner-up that outscores a top 3 pick is not in the top 3 (WF4P
// explains it in one sentence): variety (same activity as a top 3 pick) or pay.
const lowestTop3Score = Math.min(...top3.map(c => c.normalized_score));
const skippedTitles = new Set(skippedForVariety.map(c => c.career_title));
const heldBack = (career) => {
  if (!(career.normalized_score > lowestTop3Score)) return { reason: null, similar: null };
  if (skippedTitles.has(career.career_title)) {
    const twin = top3.find(p => sameFamily(p, career));
    return { reason: 'variety', similar: twin ? twin.career_title : null };
  }
  if (needsIncome && payTier(career) > 0) return { reason: 'pay', similar: null };
  return { reason: null, similar: null };
};

// Format Runner-ups
const formattedRunnerUps = runnerUps.map(career => ({
  held_back_reason: heldBack(career).reason,
  similar_to_top3: heldBack(career).similar,
  rank: career.rank,
  career_title: career.career_title,
  company_size_type: career.company_size_type || "Unknown",
  compatibility_score: career.normalized_score,
  key_strengths: career.extracted_strengths,
  brief_justification: career.extracted_strengths
    ? career.extracted_strengths.substring(0, 200)
    : `Strong alignment with ${career.normalized_score}% compatibility.`,
  happiness_pattern: career.step2_pattern_analysis?.happiness_pattern_match?.pattern || "N/A",
  burnout_risk: career.penalties?.burnout_risk?.risk_level || "N/A"
}));

// All ranked for context (Outside Box & Dream Job prompts) — also deduped
const allRankedForContext = rankedCareers.map(career => ({
  rank: career.rank,
  career_title: career.career_title,
  company_size_type: career.company_size_type,
  compatibility_score: career.normalized_score,
  happiness_pattern: career.step2_pattern_analysis?.happiness_pattern_match?.pattern || "N/A",
  burnout_risk: career.penalties?.burnout_risk?.risk_level || "N/A",
  key_strengths: career.extracted_strengths?.substring(0, 100) || ""
}));

return [{
  json: {
    career_recommendations: {
      report_generated: new Date().toISOString(),
      top_3_careers: formattedTop3,
      runner_up_careers: formattedRunnerUps,
      hours_check: {
        wanted_time: facts.time || null,
        wanted_hours_per_week: wanted,
        top3_honest_hours: top3Hours,
        combine_needed: combineNeeded
      },
      all_ranked_careers: allRankedForContext,
      summary: {
        total_careers_evaluated: sortedCareers.length,
        unique_titles_after_dedup: rankedCareers.length,
        duplicates_dropped: droppedDuplicates.length,
        blocked_by_gate: rankedCareers.filter(c => c.blocked_by_gate).map(c => c.career_title),
        skipped_for_variety: skippedForVariety.map(c => c.career_title),
        pay_rule: { needs_income: needsIncome, reordered: payReordered },
        hours_adjusted: rankedCareers.filter(c => c.hours_fit && c.hours_fit.adjustment).map(c => ({ career_title: c.career_title, adjustment: c.hours_fit.adjustment })),
        dropped_duplicates: droppedDuplicates,
        top_tier_count: top3.length,
        runner_up_count: runnerUps.length,
        careers_above_threshold: rankedCareers.filter(c => c.normalized_score >= 55).length,
        careers_discarded: rankedCareers.length - rankedCareers.filter(c => c.normalized_score >= 55).length,
        discarded_reason: "Careers ranked 11+ or scoring below 55 have been excluded due to insufficient compatibility."
      }
    }
  }
}];

// n8n Function Node - Fast reordering for LLM consumption
// No expensive formatting - LLMs handle mixed data formats well

const items = $input.all();

return items.map(item => {
  const data = item.json.career_data || item.json;

  // Simple reordering - no array formatting or parsing
  return {
    json: {
      // === PRIMARY INFORMATION ===
      career_title: data.career_title,
      overview: data.overview,
      salary: data.salary,
      company_size_type: data.company_size_type,

      // === CORE WORK DETAILS ===
      typical_tasks: data.typical_tasks,
      technical_skills: data.technical_skills,
      soft_skills: data.soft_skills,
      education_requirements: data.education_requirements,

      // === WORK ENVIRONMENT ===
      work_schedule: data.work_schedule,
      autonomy_vs_collaboration: data.autonomy_vs_collaboration,
      client_interaction: data.client_interaction,
      colleague_interaction: data.colleague_interaction,

      // === CAREER DEVELOPMENT ===
      career_progression: data.career_progression,
      motivational_factors: data.motivational_factors,
      leadership_challenges: data.leadership_challenges,

      // === METADATA ===
      id: data.id,
      ai_impact_rating: data.ai_impact_rating,
      created_at: data.created_at,
      updated_at: data.updated_at
    }
  };
});

// Get report_id from upstream node
const reportId = $node["Pull Profile Sections"].json.report_id;
// Get the outside box careers text from the upstream node
const fullText = $json.text;

// Subheaders to convert to h5 tags
const __lang = ($('Pull Profile Sections').first().json.language === 'nl') ? 'nl' : 'en';
const OUTSIDE_BOX_SUBHEADERS_ALL = {
  en: ["Overview", "Why this might be a fit", "Path Type & Reality", "AI Impact on this role"],
  nl: ["Overzicht", "Waarom dit bij u past", "Type pad & realiteit", "AI-impact op deze rol"]
};
const OUTSIDE_BOX_SUBHEADERS = OUTSIDE_BOX_SUBHEADERS_ALL[__lang];

// Function to format subheaders to h5 tags and bold AI rating
function formatSubheaders(content) {
  let formatted = content;

  // Convert subheaders to h5 tags
  OUTSIDE_BOX_SUBHEADERS.forEach(subheader => {
    // Match subheader with optional markdown bold (**), colon, or newline
    const regex = new RegExp(`(^|\\n)\\*?\\*?${subheader}\\*?\\*?:?\\s*`, 'gi');
    formatted = formatted.replace(regex, `$1<h5>${subheader}</h5>\n\n`);
  });

  // Bold the AI impact rating (e.g., "Augmented -", "At Risk -", "Displaced -")
  formatted = formatted.replace(/\n(Minimal|Moderate|High|Severe|Critical|Augmented|At Risk|Displaced|Enhanced|Transformed)(\s*-)/gi, '\n<strong>$1</strong>$2');

  // Clean up any leftover markdown bold markers
  formatted = formatted.replace(/\*\*(.*?)\*\*/g, '$1');

  return formatted.trim();
}

// Function to extract title and return cleaned content
function parseCareer(content) {
  const lines = content.trim().split('\n');
  let title = '';
  let contentStartIndex = 0;

  // Look for title patterns
